'use strict';
const clinicsData = [
{id:0,name:'せたがや訪問歯科クリニック',distance:'2.1km',rating:'4.9',reviews:128,earliest:'明日 11:00〜',transportFee:'無料（0円）',specialties:['denture','care','pain'],tags:['認知症対応','寝たきり可','女性医師在籍','土日訪問可'],badge:'訪問診療のサンプル医院',description:'ポータブルユニット・レントゲンなどの設備紹介を表示する画面例です。',doctor:'院長 高橋 誠一（サンプル）'},
{id:1,name:'さくら新町在宅歯科・嚥下クリニック',distance:'4.3km',rating:'4.8',reviews:94,earliest:'明後日 13:30〜',transportFee:'無料（0円）',specialties:['swallow','care','denture'],tags:['VE検査対応','認知症対応','寝たきり可','女性医師在籍'],badge:'嚥下の相談に対応する医院の画面例',description:'嚥下内視鏡検査や摂食機能療法など、医院の診療内容を表示するためのサンプルです。',doctor:'訪問部長 佐々木 彩香（サンプル）'},
{id:2,name:'三軒茶屋ハートフル訪問歯科',distance:'1.4km',rating:'4.7',reviews:62,earliest:'明日 15:00〜',transportFee:'無料（0円）',specialties:['denture','pain','care'],tags:['寝たきり可','土日訪問可'],badge:'訪問先からの距離・対応内容の画面例',description:'入れ歯調整や歯の痛みに関する診療内容、多職種連携の情報を紹介するサンプルです。',doctor:'院長 中村 健太郎（サンプル）'},
{id:3,name:'東京メディカルケア在宅歯科センター',distance:'6.8km',rating:'4.8',reviews:210,earliest:'月曜 10:00〜',transportFee:'無料（0円）',specialties:['care','swallow','denture'],tags:['認知症対応','寝たきり可','VE検査対応'],badge:'介護施設・病院向けの訪問診療の画面例',description:'介護施設や個人宅での口腔ケアについて紹介する画面例です。',doctor:'センター長 渡辺 隆（サンプル）'}];
let activeTagFilters=new Set(),toastTimer,lastFocus=null;
const byId=id=>document.getElementById(id);
function renderClinics(){
 const symptom=byId('web-search-symptom').value;
 const filtered=clinicsData.filter(c=>(symptom==='all'||c.specialties.includes(symptom))&&[...activeTagFilters].every(t=>c.tags.includes(t)));
 if(byId('clinic-sort').value==='distance')filtered.sort((a,b)=>parseFloat(a.distance)-parseFloat(b.distance));
 byId('clinic-count-badge').textContent=filtered.length+'件';
 byId('web-clinic-list').innerHTML=filtered.length?filtered.map((c,i)=>`<div class="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm hover:shadow-md hover:border-teal-300 transition"><div class="flex flex-wrap justify-between gap-2 mb-2"><div class="flex gap-2 items-center"><span class="bg-teal-600 text-white text-xs w-6 h-6 rounded-full flex items-center justify-center">${i+1}</span><span class="text-xs bg-teal-50 text-teal-700 px-2 py-1 rounded-full">${c.badge}</span></div><span class="text-xs text-slate-500">距離例：${c.distance}</span></div><div class="grid md:grid-cols-12 gap-4 items-center"><div class="md:col-span-8"><h3 class="text-lg font-bold mb-1">${c.name}</h3><p class="text-xs text-slate-500 mb-2">${c.doctor}</p><p class="text-xs text-slate-600 mb-3">${c.description}</p><div class="flex flex-wrap gap-1.5">${c.tags.map(t=>`<span class="text-[11px] bg-slate-100 px-2 py-1 rounded-md">${t}</span>`).join('')}</div></div><div class="md:col-span-4 bg-slate-50 p-3.5 rounded-xl border space-y-2.5 text-xs"><div class="flex justify-between border-b pb-2"><span>訪問可能枠（例）</span><b class="text-teal-700">${c.earliest}</b></div><div class="flex justify-between"><span>交通費（例）</span><b>${c.transportFee}</b></div><button onclick="openBookingModal(${c.id})" class="w-full bg-orange-500 text-white font-bold p-2.5 rounded-xl">訪問リクエスト・無料相談（デモ）</button></div></div></div>`).join(''):'<div class="bg-white p-8 rounded-2xl border text-center"><p class="font-bold mb-3">条件に一致するサンプル医院がありません</p><button onclick="resetTagFilters()" class="bg-teal-600 text-white text-xs p-2 rounded-lg">条件をリセット</button></div>';
}
function filterClinics(){renderClinics();showToast('サンプル医院を条件で絞り込みました。実際の検索・距離判定ではありません。');}
function toggleTagFilter(btn,tag){activeTagFilters.has(tag)?activeTagFilters.delete(tag):activeTagFilters.add(tag);btn.className='tag-btn text-xs px-3 py-1 rounded-full border '+(activeTagFilters.has(tag)?'bg-teal-600 text-white border-teal-600':'bg-slate-100 text-slate-700 border-slate-200');btn.setAttribute('aria-pressed',String(activeTagFilters.has(tag)));renderClinics();}
function resetTagFilters(){activeTagFilters.clear();document.querySelectorAll('.tag-btn').forEach(b=>{b.className='tag-btn text-xs bg-slate-100 text-slate-700 px-3 py-1 rounded-full border border-slate-200';b.setAttribute('aria-pressed','false');});byId('web-search-symptom').value='all';renderClinics();}
function switchPlatform(p){const web=p==='web';byId('view-web').classList.toggle('hidden',!web);byId('view-web').classList.toggle('flex',web);byId('view-ios').classList.toggle('hidden',web);byId('view-ios').classList.toggle('flex',!web);byId('btn-platform-web').className='px-3 py-2 text-xs rounded-md '+(web?'bg-teal-600':'text-slate-400');byId('btn-platform-ios').className='px-3 py-2 text-xs rounded-md '+(!web?'bg-teal-600':'text-slate-400');if(!web)setRoleButtons('user');}
function setRoleButtons(role){for(const r of ['user','clinic'])byId('btn-role-'+r).className='px-3 py-2 text-xs rounded-md '+(r===role?'bg-slate-700':'text-slate-400');}
function switchRole(role){switchPlatform('web');byId('web-user-content').classList.toggle('hidden',role!=='user');byId('web-clinic-content').classList.toggle('hidden',role!=='clinic');setRoleButtons(role);}
function setWebUserSubTab(tab){for(const t of ['search','appointments','reports']){byId('web-subtab-'+t).classList.toggle('hidden',t!==tab);byId('web-nav-'+t).className=t===tab?'text-teal-600 border-b-2 border-teal-600 font-bold':'';}}
function switchIosTab(tab){for(const t of ['home','report','chat','profile']){byId('ios-tab-'+t).classList.toggle('hidden',t!==tab);byId('ios-nav-'+t).className='flex flex-col items-center gap-1 '+(t===tab?'text-teal-600 font-bold':'text-slate-400');}byId('ios-screen-container').scrollTop=0;}
function updateCostSim(rate){if(![1,2,3].includes(rate))return;for(const r of [1,2,3])byId('sim-btn-'+r).className='py-2 rounded-lg border text-xs '+(r===rate?'border-teal-600 bg-teal-50 text-teal-700':'border-slate-200');byId('sim-cost-output').textContent='約 '+(1500*rate).toLocaleString()+'〜'+(2200*rate).toLocaleString()+' 円';}
function openModal(id){lastFocus=document.activeElement;const m=byId(id);m.classList.remove('hidden');m.classList.add('flex');document.body.style.overflow='hidden';m.querySelector('button').focus();}
function closeModal(id){const m=byId(id);m.classList.add('hidden');m.classList.remove('flex');document.body.style.overflow='';if(lastFocus)lastFocus.focus();}
function openBookingModal(id){const c=clinicsData.find(c=>c.id===id)||clinicsData[0];byId('modal-clinic-name').textContent=c.name;openModal('booking-modal');}
function closeBookingModal(){closeModal('booking-modal');}
function submitBookingRequest(){closeBookingModal();showToast('操作デモが完了しました。予約・送信は行っていません。医院から連絡は届きません。');}
function openDesignConceptModal(){openModal('concept-modal');}
function closeDesignConceptModal(){closeModal('concept-modal');}
function demoAction(name){showToast(name+'の操作デモです。通信・保存・実際の処理は行っていません。');}
function showToast(msg){byId('toast-msg').textContent=msg;byId('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>byId('toast').classList.add('hidden'),5000);}
document.addEventListener('keydown',e=>{const m=['booking-modal','concept-modal'].map(byId).find(el=>!el.classList.contains('hidden'));if(!m)return;if(e.key==='Escape')closeModal(m.id);if(e.key==='Tab'){const b=[...m.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===b[0]){e.preventDefault();b.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===b.at(-1)){e.preventDefault();b[0].focus();}}});
document.addEventListener('DOMContentLoaded',()=>{
 for(const t of ['認知症対応','寝たきり可','女性医師在籍','VE検査対応','土日訪問可']){const b=document.createElement('button');b.textContent=t;b.className='tag-btn text-xs bg-slate-100 text-slate-700 px-3 py-1 rounded-full border border-slate-200';b.setAttribute('aria-pressed','false');b.addEventListener('click',()=>toggleTagFilter(b,t));byId('tag-filters').append(b);}
 byId('clinic-kpis').innerHTML=[['新規訪問リクエスト','3 件','要回答（例）'],['本日の訪問予定','11 件','居宅8／施設3（例）'],['ルート効率スコア','94%','仮の指標'],['連携状況','確認済','サンプル']].map(([a,b,c])=>`<div class="bg-white p-4 rounded-xl border"><p class="text-xs text-slate-500">${a}</p><p class="text-2xl font-bold text-teal-600 my-1">${b}</p><p class="text-xs text-slate-400">${c}</p></div>`).join('');
 byId('ios-symptoms').innerHTML=[['入れ歯が痛い','調整・作り直し',0,'fa-teeth-open'],['むせ・飲み込み','相談の画面例',1,'fa-droplet'],['定期口腔ケア','お口の清潔保持',2,'fa-wand-magic-sparkles'],['歯の痛み・腫れ','相談の画面例',0,'fa-triangle-exclamation']].map(([a,b,id,ic])=>`<button onclick="openBookingModal(${id})" class="bg-white p-3 rounded-2xl border text-left"><i class="fa-solid ${ic} text-teal-600 mb-2"></i><p class="font-bold text-xs">${a}</p><p class="text-[10px] text-slate-400">${b}</p></button>`).join('');
 byId('ios-bottom-nav').innerHTML=[['home','ホーム','fa-house'],['report','連絡帳','fa-clipboard'],['chat','連携チャット','fa-comments'],['profile','保険証','fa-id-card']].map(([t,l,i])=>`<button onclick="switchIosTab('${t}')" id="ios-nav-${t}" class="flex flex-col items-center gap-1 ${t==='home'?'text-teal-600 font-bold':'text-slate-400'}"><i class="fa-solid ${i} text-base"></i><span>${l}</span></button>`).join('');
 for(const id of ['booking-modal','concept-modal'])byId(id).addEventListener('click',e=>{if(e.target===byId(id))closeModal(id);});renderClinics();
});
